185	// 被引用的有效上游保留自己的结果，等待该错误记录的下游级联失败并以它为根因。
186	func TestReopenRejectsSucceededRecordReferencingLaterJob(t *testing.T) {
187		dir := t.TempDir()
188		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
189		// 作业 1 总和 3，作业 5 总和 5。
190		syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
191		syntheticSucceededRecord(t, dir, 5, []int64{5}, []int64{5}, nil, base)
192		// 作业 3：依赖 [5]（后来作业），实际输入 [10,5]，sum=15、sq=125，全套自洽。
193		bad := syntheticSucceededRecord(t, dir, 3, []int64{10}, []int64{10, 5}, []uint64{5}, base)
194		if bad.archive.Sum != 15 || bad.archive.SumOfSquares != 125 {
195			t.Fatalf("premise result=%d,%d want 15,125", bad.archive.Sum, bad.archive.SumOfSquares)
196		}
197		// 作业 6：排队等待作业 3。
198		writeSyntheticRecord(t, dir, &storedJob{
199			id: 6, submitter: "a", requestID: "child",
200			values: []int64{20}, dependencies: []uint64{3},
201			queuedAt: base.Add(6 * time.Second),
202			status:   StatusQueued,
203		})
204	
205		s, err := Open(dir)
206		if err != nil {
207			t.Fatal(err)
208		}
209		defer s.Close()
210	
211		assertIllegalOrderingFailure(t, s, 3, 5, 3)
212	
213		// 被引用的后来作业与无关上游都保留成功结果，不被判成失败。
214		g1, _ := s.Get(1)
215		if g1.Status != StatusSucceeded || g1.Archive == nil || g1.Archive.Sum != 3 {
216			t.Fatalf("valid job 1 must keep its result: %+v", g1.Archive)
217		}
218		g5, _ := s.Get(5)
219		if g5.Status != StatusSucceeded || g5.Archive == nil || g5.Archive.Sum != 5 {
220			t.Fatalf("referenced later job 5 exists and succeeded; it must keep its result: %+v", g5.Archive)
221		}
222	
223		child := waitStatus(t, s, 6, StatusFailed)
224		if child.BlockerID != 3 || !strings.Contains(child.FailureReason, "直接上游作业 3") {
225			t.Fatalf("child blocker=%d reason=%q want root 3 named as direct upstream",
226				child.BlockerID, child.FailureReason)
227		}
228	}
229	
230	// 多个违反先后关系的引用时，失败原因指出保存的依赖顺序中第一个不合法作业号：
231	// 作业 7 的依赖为 [1,9,5,8]，1 合法，9 是第一个作业号不小于 7 的上游；
232	// 被引用的 8、9 都确实存在且成功，仍不能接受。
233	func TestReopenIllegalOrderingNamesFirstBadDependencyInSavedOrder(t *testing.T) {
234		dir := t.TempDir()
235		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
236		syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
237		syntheticSucceededRecord(t, dir, 5, []int64{5}, []int64{5}, nil, base)
238		syntheticSucceededRecord(t, dir, 8, []int64{8}, []int64{8}, nil, base)
239		syntheticSucceededRecord(t, dir, 9, []int64{9}, []int64{9}, nil, base)
240		// 作业 7：依赖次序 [1,9,5,8]，追加各上游总和 [3,9,5,8]，全套自洽。
241		syntheticSucceededRecord(t, dir, 7,
242			[]int64{10}, []int64{10, 3, 9, 5, 8}, []uint64{1, 9, 5, 8}, base)
243	
244		s, err := Open(dir)
245		if err != nil {
246			t.Fatal(err)
247		}
248		defer s.Close()
249	
250		assertIllegalOrderingFailure(t, s, 7, 9, 7)
251		// 被引用的作业全部保留自己的成功结果。
252		for _, id := range []uint64{1, 5, 8, 9} {
253			g, _ := s.Get(id)
254			if g.Status != StatusSucceeded || g.Archive == nil {
255				t.Fatalf("referenced job %d must stay succeeded: status=%s", id, g.Status)
256			}
257		}
258	}
259	
260	// 排队记录引用后来作业或自己时，重开后立即失败：不能开始计算（无开始时间）、
261	// 补上完成时间、落盘改写，也不能继续等待后来作业——即使后来作业随后成功。
262	// 等待该错误记录的合法下游随之级联失败；无关排队作业照常完成。
263	func TestReopenQueuedIllegalDependencyFailsWithoutWaiting(t *testing.T) {
264		dir := t.TempDir()
265		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
266		// 作业 2：排队引用后来的作业 3（作业 3 本身也在排队）。
267		writeSyntheticRecord(t, dir, &storedJob{
268			id: 2, submitter: "a", requestID: "forward",
269			values: []int64{10}, dependencies: []uint64{3},
270			queuedAt: base.Add(2 * time.Second),
271			status:   StatusQueued,
272		})
273		// 作业 3：无依赖排队，重开后应照常计算成功——作业 2 不能等它。
274		writeSyntheticRecord(t, dir, &storedJob{
275			id: 3, submitter: "a", requestID: "later",
276			values:   []int64{5},
277			queuedAt: base.Add(3 * time.Second),
278			status:   StatusQueued,
279		})
280		// 作业 5：排队引用自己。
281		writeSyntheticRecord(t, dir, &storedJob{
282			id: 5, submitter: "a", requestID: "self",
283			values: []int64{50}, dependencies: []uint64{5},
284			queuedAt: base.Add(5 * time.Second),
285			status:   StatusQueued,
286		})
287		// 作业 6：合法排队下游，等待作业 5。
288		writeSyntheticRecord(t, dir, &storedJob{
289			id: 6, submitter: "a", requestID: "child",
290			values: []int64{60}, dependencies: []uint64{5},
291			queuedAt: base.Add(6 * time.Second),
292			status:   StatusQueued,
293		})
294		// 作业 7：无关排队作业。
295		writeSyntheticRecord(t, dir, &storedJob{
296			id: 7, submitter: "b", requestID: "indep",
297			values:   []int64{1, 2, 3},
298			queuedAt: base.Add(7 * time.Second),
299			status:   StatusQueued,
300		})
301	
302		s, err := Open(dir)
303		if err != nil {
304			t.Fatal(err)
305		}
306		defer s.Close()
307	
308		assertIllegalOrderingFailure(t, s, 2, 3, 2)
309		g2, _ := s.Get(2)
310		if !g2.StartedAt.IsZero() {
311			t.Fatalf("forward-referencing queued job must never start computing, started=%s", g2.StartedAt)
312		}
313		if g2.FinishedAt.IsZero() {
314			t.Fatalf("forward-referencing queued job must be given a finished time when rejudged")
315		}
316		// 后来作业随后成功，作业 2 也不得翻案。
317		later := waitStatus(t, s, 3, StatusSucceeded)
318		if later.Archive.Sum != 5 {
319			t.Fatalf("later job sum=%d want 5", later.Archive.Sum)
320		}
321		g2b, _ := s.Get(2)
322		if g2b.Status != StatusFailed {
323			t.Fatalf("job 2 must stay failed after job 3 succeeded, got %s", g2b.Status)
324		}
325	
326		assertIllegalOrderingFailure(t, s, 5, 5, 5)
327		child := waitStatus(t, s, 6, StatusFailed)
328		if child.BlockerID != 5 || !strings.Contains(child.FailureReason, "直接上游作业 5") {
329			t.Fatalf("child blocker=%d reason=%q want root 5 named as direct upstream",
330				child.BlockerID, child.FailureReason)
331		}
332		if !child.StartedAt.IsZero() || child.Archive != nil {
333			t.Fatalf("blocked child must never compute: started=%s archive=%v",
334				child.StartedAt, child.Archive)
335		}
336	
337		indep := waitStatus(t, s, 7, StatusSucceeded)
338		if indep.Archive.Sum != 6 {
339			t.Fatalf("unrelated job sum=%d want 6", indep.Archive.Sum)
340		}
341	}
342	
343	// 已经失败或取消的记录即使保存了违反先后关系的依赖，也保留既有终态、原因与
344	// 根因，不被恢复阶段的先后检查改写。
345	func TestReopenIllegalOrderingKeepsExistingTerminalRecords(t *testing.T) {
346		dir := t.TempDir()
347		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
348		syntheticSucceededRecord(t, dir, 1, []int64{1}, []int64{1}, nil, base)
349		failedAt := base.Add(2 * time.Second)
350		writeSyntheticRecord(t, dir, &storedJob{
351			id: 2, submitter: "a", requestID: "f",
352			values: []int64{10}, dependencies: []uint64{5}, // 引用后来作业
353			queuedAt: failedAt, finishedAt: failedAt,
354			status:        StatusFailed,
355			failureReason: "既有的失败原因",
356			blockerID:     9,
357		})
358		writeSyntheticRecord(t, dir, &storedJob{
359			id: 3, submitter: "a", requestID: "c",
360			values: []int64{11}, dependencies: []uint64{3}, // 引用自己
361			queuedAt: base.Add(3 * time.Second), finishedAt: base.Add(4 * time.Second),
362			status: StatusCanceled,
363		})
364	
365		s, err := Open(dir)
366		if err != nil {
367			t.Fatal(err)
368		}
369		defer s.Close()
370	
371		gf, _ := s.Get(2)
372		if gf.Status != StatusFailed || gf.BlockerID != 9 || gf.FailureReason != "既有的失败原因" {
373			t.Fatalf("existing failed record must be preserved: status=%s blocker=%d reason=%q",
374				gf.Status, gf.BlockerID, gf.FailureReason)
375		}
376		gc, _ := s.Get(3)
377		if gc.Status != StatusCanceled || gc.BlockerID != 0 || gc.FailureReason != "" {
378			t.Fatalf("existing canceled record must be preserved: status=%s blocker=%d reason=%q",
379				gc.Status, gc.BlockerID, gc.FailureReason)
380		}
381	}
382	
383	// 同时违反唯一性与先后关系时，保留现有的重复依赖失败说明（重复检查先行）。
384	func TestReopenDuplicateCheckTakesPrecedenceOverOrdering(t *testing.T) {
385		dir := t.TempDir()
386		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
387		syntheticSucceededRecord(t, dir, 9, []int64{9}, []int64{9}, nil, base)
388		// 作业 3：依赖 [9,9]——既重复引用，作业号 9 又大于自己；原因必须是重复说明。
389		syntheticSucceededRecord(t, dir, 3,
390			[]int64{10}, []int64{10, 9, 9}, []uint64{9, 9}, base)
391	
392		s, err := Open(dir)
393		if err != nil {
394			t.Fatal(err)
395		}
396		defer s.Close()
397	
398		g, err := s.Get(3)
399		if err != nil {
400			t.Fatal(err)
401		}
402		if g.Status != StatusFailed || g.BlockerID != 0 {
403			t.Fatalf("job 3 must fail with blocker 0: status=%s blocker=%d", g.Status, g.BlockerID)
404		}
405		if !strings.Contains(g.FailureReason, "依赖列表重复") ||
406			strings.Contains(g.FailureReason, "依赖先后关系不合法") {
407			t.Fatalf("duplicate reason must be preserved over ordering reason: %q", g.FailureReason)
408		}
409	}
410	
411	// 旧的单依赖记录（落盘只有 has_dependency/dependency_id）适用同一规则：
412	// dependency_id 等于或大于本作业号时同样改判失败。
413	func TestReopenLegacySingleDependencyObeysOrderingRule(t *testing.T) {
414		dir := t.TempDir()
415		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
416		// 作业 6：旧格式成功记录，单依赖指向自己（实际输入 [0,0]，全套自洽）。
417		j6 := &storedJob{
418			id: 6, submitter: "a", requestID: "legacy-self",
419			values:     []int64{0},
420			queuedAt:   base.Add(6 * time.Second),
421			startedAt:  base.Add(6*time.Second + time.Millisecond),
422			finishedAt: base.Add(7 * time.Second),
423			status:     StatusSucceeded,
424		}
425		eff6 := []int64{0, 0}
426		sum, sumSq, _, ok := computeResult(eff6, 0, nil)
427		if !ok {
428			t.Fatal("eff overflows")
429		}
430		a6 := newArchive(&storedJob{
431			id: 6, submitter: "a", requestID: "legacy-self",
432			values: []int64{0}, dependencies: []uint64{6},
433		}, eff6, sum, sumSq, j6.finishedAt)
434		r6 := jobRecord{
435			Version: recordVersion,
436			ID:      6, Submitter: "a", RequestID: "legacy-self",
437			// Dependencies 刻意留空（omitempty 后落盘无此字段）。
438			HasDependency: true, DependencyID: 6,
439			QueuedAt: j6.queuedAt, StartedAt: j6.startedAt, FinishedAt: j6.finishedAt,
440			Status:          StatusSucceeded,
441			EffectiveValues: append([]int64(nil), eff6...),
442			Archive:         a6,
443		}
444		writeRawRecord(t, dir, 6, &r6)
445	
446		// 作业 7：旧格式排队记录，单依赖指向后来的作业 8。
447		r7 := jobRecord{
448			Version: recordVersion,
449			ID:      7, Submitter: "a", RequestID: "legacy-forward",
450			Values: []int64{0},
451			// Dependencies 刻意留空。
452			HasDependency: true, DependencyID: 8,
453			QueuedAt: base.Add(7 * time.Second),
454			Status:   StatusQueued,
455		}
456		writeRawRecord(t, dir, 7, &r7)
457	
458		s, err := Open(dir)
459		if err != nil {
460			t.Fatal(err)
461		}
462		defer s.Close()
463	
464		assertIllegalOrderingFailure(t, s, 6, 6, 6)
465		assertIllegalOrderingFailure(t, s, 7, 8, 7)
466		g7, _ := s.Get(7)
467		// 旧格式字段恢复后依赖列表恰含一个作业号，原始内容保留。
468		if len(g7.Dependencies) != 1 || g7.Dependencies[0] != 8 ||
469			len(g7.Values) != 1 || g7.Values[0] != 0 || !g7.HasDependency || g7.DependencyID != 8 {
470			t.Fatalf("legacy queued record must keep the reconstructed single dependency: %+v", g7)
471		}
472	}
473	
474	// 不要求依赖列表按作业号排序：所有直接上游作业号都小于自己时，乱序列表
475	// （如 [3,1,2]）仍属合法，重开后保持成功，追加仍按保存的原次序，结果不变。
476	func TestReopenUnsortedButEarlierDependenciesRemainLegal(t *testing.T) {
477		dir := t.TempDir()
478		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
479		syntheticSucceededRecord(t, dir, 1, []int64{1}, []int64{1}, nil, base) // sum 1
480		syntheticSucceededRecord(t, dir, 2, []int64{2}, []int64{2}, nil, base) // sum 2
481		syntheticSucceededRecord(t, dir, 3, []int64{3}, []int64{3}, nil, base) // sum 3
482		// 作业 5：依赖次序 [3,1,2]（乱序但作业号都小于 5），追加 [3,1,2]。
483		down := syntheticSucceededRecord(t, dir, 5,
484			[]int64{10}, []int64{10, 3, 1, 2}, []uint64{3, 1, 2}, base)
485	
486		s, err := Open(dir)
487		if err != nil {
488			t.Fatal(err)
489		}
490		defer s.Close()
491	
492		g, err := s.Get(5)
493		if err != nil {
494			t.Fatal(err)
495		}
496		if g.Status != StatusSucceeded || g.Archive == nil {
497			t.Fatalf("unsorted but earlier upstreams must stay legal: %s", g.Status)
498		}
499		if g.Archive.Sum != down.archive.Sum || g.Archive.SumOfSquares != down.archive.SumOfSquares ||
500			g.Archive.Checksum != down.archive.Checksum {
501			t.Fatalf("legal unsorted result changed: got %+v want %+v", g.Archive, down.archive)
502		}
503		if len(g.Dependencies) != 3 || g.Dependencies[0] != 3 || g.Dependencies[1] != 1 || g.Dependencies[2] != 2 {
504			t.Fatalf("dependency order must be preserved: %v", g.Dependencies)
505		}
506	}
507	
508	// writeRawRecord 直接把给定记录结构序列化落盘，用于构造旧格式单依赖记录。
509	func writeRawRecord(t *testing.T, dir string, id uint64, r *jobRecord) {
510		t.Helper()
511		out, err := json.MarshalIndent(r, "", "  ")
512		if err != nil {
513			t.Fatal(err)
514		}
515		if err := writeFileAtomic(dir, jobFileName(id), out, 0o600); err != nil {
516			t.Fatal(err)
517		}
518	}
